/** Capture-derived recipe bridge, independent of Source saved part scalar reconstruction. */
final class NativeRampAssemblyChecks {
 private static int parts;private static long maximumBytes;
 static void replay(ServerLevel level,NativeRampEntity owner,NativeRampCapture.Plan plan,JsonObject reference,BlockPos root)throws Exception{
  var snapshots=new HashMap<BlockPos,CompoundTag>();for(var source:plan.sources()){var tile=level.getBlockEntity(source.position());if(tile!=null)snapshots.put(source.position(),tile.saveWithFullMetadata(level.registryAccess()));}
  var assembly=NativeRampAssembly.prepare(root,owner.settings(),plan,snapshots);maximumBytes=Math.max(maximumBytes,assembly.retainedBytes());
  for(var stateElement:reference.getAsJsonArray("states")){var state=stateElement.getAsJsonObject();long time=TagParser.parseTag(state.get("saved").getAsString()).getLong("LastStepTick");for(var element:state.getAsJsonArray("parts")){var part=element.getAsJsonObject();var p=part.getAsJsonArray("position");var cell=root.offset(p.get(0).getAsInt()-4,p.get(1).getAsInt()-80,p.get(2).getAsInt()-4);var tag=TagParser.parseTag(part.get("saved").getAsString());double target=tag.contains("RampTargetPose",Tag.TAG_DOUBLE)?tag.getDouble("RampTargetPose"):tag.getBoolean("Open")?1:0;var motion=new NativeRampPartData.Motion(1,tag.getLong("StartTick"),tag.getDouble("StartPose"),target,tag.getInt("Duration"),tag.getBoolean("Moving"),0);var data=assembly.part(cell,motion,NativeRampPartData.Belt.NONE);var actual=new ArrayList<AABB>();for(var piece:NativeRampGeometry.snapshot(data.spec(),motion.pose(time,.25)).pieces())actual.add(piece.box());var expected=new ArrayList<AABB>();for(var boxElement:part.getAsJsonArray("boxes")){var b=boxElement.getAsJsonArray();expected.add(new AABB(b.get(0).getAsDouble(),b.get(1).getAsDouble(),b.get(2).getAsDouble(),b.get(3).getAsDouble(),b.get(4).getAsDouble(),b.get(5).getAsDouble()));}Comparator<AABB> order=Comparator.comparingDouble((AABB b)->b.minX).thenComparingDouble(b->b.minY).thenComparingDouble(b->b.minZ).thenComparingDouble(b->b.maxX).thenComparingDouble(b->b.maxY).thenComparingDouble(b->b.maxZ);actual.sort(order);expected.sort(order);if(actual.size()!=expected.size())throw new AssertionError("Capture-derived part component count mode="+reference.get("mode")+" cell="+cell);for(int i=0;i<actual.size();i++){var a=actual.get(i);var b=expected.get(i);double delta=Math.abs(a.minX-b.minX)+Math.abs(a.minY-b.minY)+Math.abs(a.minZ-b.minZ)+Math.abs(a.maxX-b.maxX)+Math.abs(a.maxY-b.maxY)+Math.abs(a.maxZ-b.maxZ);if(delta>1e-9)throw new AssertionError("Capture-derived part geometry mode="+reference.get("mode")+" cell="+cell+" delta="+delta);}if(!NativeRampPartData.read(data.write(),cell,level.registryAccess()).write().equals(data.write()))throw new AssertionError("Generated body codec");parts++;}}
  for(var source:plan.sources())if(level.getBlockState(source.position())!=source.state())throw new AssertionError("Recipe builder mutated source");
 }
 static void materials(ServerLevel level,NativeRampEntity owner,net.minecraft.server.level.ServerPlayer actor){
  var seed=owner.getBlockPos().relative(owner.scanFacing());int cases=0;
  for(var face:Direction.values()){
   var state=com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get().defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,face);level.setBlock(seed,state,18);var tile=(com.vandorlabs.neoforge.ProgrammableBlockEntity)level.getBlockEntity(seed);var tag=new CompoundTag();tag.putInt("housingTexture",7);tag.putInt("HousingTextureVersion",1);tag.putInt("MainTextureLayout",2);tag.putBoolean("FaceTexturesEnabled",true);tag.putIntArray("FaceTextures",new int[]{0,1,2,3,4,5});tag.putByteArray("PrivateRampSnapshot",new byte[65536]);tile.loadWithComponents(tag,level.registryAccess());var plan=NativeRampCapture.select(owner,actor);if(!plan.accepted())throw new AssertionError("Native material selection "+plan.error());var snapshot=tile.saveWithFullMetadata(level.registryAccess());var assembly=NativeRampAssembly.prepare(owner.getBlockPos(),owner.settings(),plan.plan(),Map.of(seed,snapshot));snapshot.putInt("housingTexture",123);snapshot.getIntArray("FaceTextures")[0]=123;var data=assembly.part(assembly.cells(0,0).iterator().next(),new NativeRampPartData.Motion(1,0,0,0,1,false,0),NativeRampPartData.Belt.NONE);var material=data.origins().getFirst().material();if(material.mainTexture()!=tile.settings().mainTexture||material.layout()!=2||material.rotation()!=((2-(face.get2DDataValue()&3))&3)||!material.facesEnabled()||material.face(0)!=0||data.write().toString().contains("PrivateRampSnapshot"))throw new AssertionError("Bounded staged native material "+face);cases++;level.setBlock(seed,Blocks.AIR.defaultBlockState(),18);
  }
  if(parts!=9322)throw new AssertionError("All capture-derived Source part bodies "+parts);System.out.println("[vandorlabs][ramp-assembly] PASS generatedBodies="+parts+" nativeMaterials="+cases+" maximumBytes="+maximumBytes+" capture-derived translated geometry/typed body codec, no mutation authority");
 }
}
